package com.gmail.manhle240406.project.pet;
import android.content.*;import android.graphics.*;import android.net.Uri;import androidx.lifecycle.ViewModelProvider;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import com.gmail.manhle240406.project.R;import com.gmail.manhle240406.project.adoption.*;import com.gmail.manhle240406.project.media.MediaDraftViewModel;import com.google.firebase.auth.FirebaseAuth;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.concurrent.atomic.AtomicReference;import static org.junit.Assert.*;import static org.hamcrest.Matchers.*;import static androidx.test.espresso.Espresso.*;import static androidx.test.espresso.action.ViewActions.*;import static androidx.test.espresso.matcher.ViewMatchers.*;
@RunWith(AndroidJUnit4.class) public class Oc3PetRegistrationLiveTest {
 private static String privateId(Object model,String key){try{java.lang.reflect.Field f=PetRegistrationModel.class.getDeclaredField(key);f.setAccessible(true);return (String)f.get(model);}catch(Exception e){throw new AssertionError(e);}}
 @Test public void syntheticPhotoRegistersOnceAndAppearsInReviewerQueue()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();String uid=FirebaseAuth.getInstance().getUid();assertNotNull(uid);OwnedPets.clear();JSONObject result=new JSONObject().put("uid",uid);java.io.File photo=new java.io.File(c.getCacheDir(),"oc3-synthetic-pet.jpg");Bitmap b=Bitmap.createBitmap(96,96,Bitmap.Config.ARGB_8888);b.eraseColor(Color.rgb(40,110,70));try(java.io.FileOutputStream out=new java.io.FileOutputStream(photo)){b.compress(Bitmap.CompressFormat.JPEG,90,out);}b.recycle();UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());
  try{try(ActivityScenario<PetActivity> scenario=ActivityScenario.launch(PetActivity.class)){assertTrue(device.wait(Until.hasObject(By.text(c.getString(R.string.ad_add_pet))),30000));onView(withText(R.string.ad_add_pet)).perform(click());onView(withTagValue(equalTo("pet_name"))).perform(scrollTo(),replaceText("QA OC3 synthetic registration"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());scenario.onActivity(a->{PetRegistrationModel m=new ViewModelProvider(a).get(PetRegistrationModel.class);MediaDraftViewModel media=new ViewModelProvider(a).get(MediaDraftViewModel.class);media.add(java.util.Arrays.asList(Uri.fromFile(photo)));try{result.put("petId",privateId(m,"petId")).put("operationId",privateId(m,"operationId")).put("assets",new JSONArray(media.ids()));}catch(Exception e){throw new AssertionError(e);}});assertTrue("Synthetic Android JPEG upload completes",device.wait(Until.hasObject(By.text(c.getString(R.string.feedback_cover_photo))),90000));onView(withTagValue(equalTo("pet_register_submit"))).perform(scrollTo(),click());assertTrue("Real registration has success feedback",device.wait(Until.hasObject(By.text(c.getString(R.string.feedback_pet_registered))),45000));assertEquals(uid,FirebaseAuth.getInstance().getUid());device.takeScreenshot(new java.io.File(c.getExternalFilesDir(null),"oc3-pet-registered.png"));}
   try(ActivityScenario<AdoptionFlowActivity> scenario=ActivityScenario.launch(new Intent(c,AdoptionFlowActivity.class).putExtra("mode","review"))){assertTrue("Existing reviewer sees submitted pet",device.wait(Until.hasObject(By.textContains("QA OC3 synthetic registration")),30000));device.takeScreenshot(new java.io.File(c.getExternalFilesDir(null),"oc3-pet-review-queue.png"));}
   result.put("passed",true);
  }finally{java.nio.file.Files.write(new java.io.File(c.getExternalFilesDir(null),"oc3-pet-results.json").toPath(),result.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));photo.delete();}
 }
}
